pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        bool ok = false;
        string memory v;
        if (seed < type(uint256).max) {
            try c.version() returns (string memory r) { ok = true; v = r; } catch { ok = false; }
        } else {
            try c.version() returns (string memory r) { ok = true; v = r; } catch { ok = false; }
        }
        assertTrue(ok && keccak256(bytes(v)) == keccak256(bytes("1.0.0")));
    }
}

